<?php
require_once __DIR__.'/../includes/init.php';require_admin();$admin=current_user();
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$id=(int)($_POST['id']??0);db()->prepare("UPDATE reports SET status='resolved',resolved_by=?,resolved_at=NOW() WHERE id=?")->execute([$admin['id'],$id]);flash('success','Report resolved.');redirect('admin/reports.php');}
$stmt=db()->query("SELECT r.*,u.name reporter_name,resolver.name resolver_name FROM reports r JOIN users u ON u.id=r.reporter_id LEFT JOIN users resolver ON resolver.id=r.resolved_by ORDER BY FIELD(r.status,'pending','resolved'),r.created_at DESC");$reports=$stmt->fetchAll();$pageTitle='Admin Reports - Campus Connect';include __DIR__.'/_admin_header.php';
?>
<div class="admin-title"><div><h1>Reports</h1><p>Review community reports and mark completed investigations resolved.</p></div></div><section class="report-admin-list"><?php foreach($reports as $report): $target=report_target($report['target_type'],(int)$report['target_id']); ?><article class="admin-report-card status-<?= e($report['status']) ?>"><div><span class="admin-status status-<?= e($report['status']) ?>"><?= e(ucfirst($report['status'])) ?></span><h2><?= e($report['reason']) ?></h2><p><strong><?= e(ucfirst($report['target_type'])) ?>:</strong> <?= e($target['label']??'Deleted or unavailable') ?></p><p><?= nl2br(e($report['details']?:'No extra details supplied.')) ?></p><small>Reported by <?= e($report['reporter_name']) ?> · <?= e(time_ago($report['created_at'])) ?></small><?php if($report['status']==='resolved'): ?><small>Resolved by <?= e($report['resolver_name']?:'Admin') ?></small><?php endif; ?></div><?php if($report['status']==='pending'): ?><form method="post"><?= csrf_field() ?><input type="hidden" name="id" value="<?= (int)$report['id'] ?>"><button class="success">Mark Resolved</button></form><?php endif; ?></article><?php endforeach; ?><?php if(!$reports): ?><div class="admin-empty">No reports submitted.</div><?php endif; ?></section>
<?php include __DIR__.'/_admin_footer.php'; ?>
